local config = {
  str_homestory_N19chuanshanjia_90010101_1_dialog_content = "Cloud Gardens ha estado bastante animado últimamente.",
  str_homestory_N19chuanshanjia_90010101_2_dialog_content = "¿Derecha? Parece que hay muchos más animales aquí que antes.",
  str_homestory_N19chuanshanjia_90010101_3_dialog_content = "Pero sabes, todavía tengo curiosidad acerca de esa criatura con armadura escamosa de la que todos hablan. ¿Cómo se llamaba de nuevo?",
  str_homestory_N19chuanshanjia_90010101_4_dialog_content = "los <color=#FFB400>Pangalo lítico</color>?",
  str_homestory_N19chuanshanjia_90010101_5_dialog_content = "¡Sí!",
  str_homestory_N19chuanshanjia_90010101_6_dialog_content = "Parecen ser capaces de excavar a través de las montañas y el suelo. Fascinante.",
  str_homestory_N19chuanshanjia_90010101_7_dialog_content = "¿Qué es ese sonido?",
  str_homestory_N19chuanshanjia_90010101_8_dialog_content = "¡De esa manera!",
  str_homestory_N19chuanshanjia_90010101_9_dialog_content = "Cubierto de escamas de los pies a la cabeza, con una cola enorme... ¿Podría ser un Pangalo justo en frente de nosotros?",
  str_homestory_N19chuanshanjia_90010101_10_dialog_content = "Hola.",
  str_homestory_N19chuanshanjia_90010101_11_dialog_content = "¿Están ustedes dos familiarizados con este lugar, por casualidad? Hmm, según mis años de conocimiento y experiencia...",
  str_homestory_N19chuanshanjia_90010101_12_dialog_content = "Solo puedo suponer que tú estás a cargo aquí, ¿no?",
  str_homestory_N19chuanshanjia_90010101_13_dialog_content = "¿Cómo lo supiste?",
  str_homestory_N19chuanshanjia_90010101_14_dialog_content = "E-Espera, Vice, ¿También puedes escuchar sus pensamientos?",
  str_homestory_N19chuanshanjia_90010101_15_dialog_content = "¿Qué quieres decir con \"pensamientos\"? Claramente nos está hablando...",
  str_homestory_N19chuanshanjia_90010101_16_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010101_17_dialog_content = "<size=65>¡Dios mío, está hablando!</size>",
  str_homestory_N19chuanshanjia_90010101_18_dialog_content = "De hecho estoy hablando, sí.",
  str_homestory_N19chuanshanjia_90010101_19_dialog_content = "Y para que conste, mi nombre es <color=#FFB400>sahn</color>. Por favor, absténgase de referirse a mí como \"eso\" de ahora en adelante, gracias.",
  str_homestory_N19chuanshanjia_90010101_20_dialog_content = "¡Ay! Su nombre es Sahn!",
  str_homestory_N19chuanshanjia_90010101_21_dialog_content = "¡Eso es \"él\", no \"su\"! Suspiro, puedo decir que eres joven para tu especie, pero por favor muestra un poco más de respeto a tus mayores.",
  str_homestory_N19chuanshanjia_90010101_22_dialog_content = "Lo siento mucho. A juzgar por tu larga y espesa barba, estoy seguro de que tienes años de sabiduría y experiencia para compartir.",
  str_homestory_N19chuanshanjia_90010101_23_dialog_content = "Un animal que puede hablar... ¿Podría ser uno de esos <color=#FFB400>demi-humanos</color> de las leyendas?",
  str_homestory_N19chuanshanjia_90010101_24_dialog_content = "Leyendas?",
  str_homestory_N19chuanshanjia_90010101_25_dialog_content = "¿Qué pasó con los demi-humanos?",
  str_homestory_N19chuanshanjia_90010101_26_dialog_content = "*Tose* Er, tendrás que perdonar a mi amigo, Sahn. Creo que es solo porque hace mucho que no ve un pangalo lítico.",
  str_homestory_N19chuanshanjia_90010101_27_dialog_content = "¿En serio? ¡Porque parece bastante sorprendida ante la idea de un animal que habla, si me preguntas!",
  str_homestory_N19chuanshanjia_90010101_28_dialog_content = "¡Conocemos muchos animales que hablan! Derecha, Vice?",
  str_homestory_N19chuanshanjia_90010101_29_dialog_content = "¿Eh?",
  str_homestory_N19chuanshanjia_90010101_30_dialog_content = "(No creo que Sahn sepa que los demi-humanos ya no están...)",
  str_homestory_N19chuanshanjia_90010101_31_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010101_32_dialog_content = "¡Ay! R-Claro!",
  str_homestory_N19chuanshanjia_90010101_33_dialog_content = "¿Crees que nací ayer? ¡Es muy obvio que ella dudó justo ahora!",
  str_homestory_N19chuanshanjia_90010101_34_dialog_content = "Er, sí, bueno... Es un placer conocerte, Sahn. Me llamo Vice, y esto es PlayerName.",
  str_homestory_N19chuanshanjia_90010101_35_dialog_content = "Él está a cargo aquí, y nunca te mentiría.",
  str_homestory_N19chuanshanjia_90010101_36_dialog_content = "Los animales parlantes que mencionó son nuestros amigos.",
  str_homestory_N19chuanshanjia_90010101_37_dialog_content = "Si todavía no estás convencido, entonces PlayerName solo tendré que traerlos para que los veas.",
  str_homestory_N19chuanshanjia_90010101_38_dialog_content = "Déjame pensar.",
  str_homestory_N19chuanshanjia_90010101_39_dialog_content = "(¿No vi <color=#FFB400>Korgon</color> cerca del borde del bosque antes? ¡Puedo traerlo aquí!)",
  str_homestory_N19chuanshanjia_90010101_40_dialog_content = "¡Ay! ¡S-Sí! ¡Por favor, espera aquí un momento, Sahn!",
  str_homestory_N19chuanshanjia_90010101_41_dialog_content = "(No digas nada sobre los demi-humanos mientras no estoy, ¿entiendes?)",
  str_homestory_N19chuanshanjia_90010101_42_dialog_content = "(¡O-Por supuesto! Solo date prisa, ¿de acuerdo?)",
  str_homestory_N19chuanshanjia_90010111_1_dialog_content = "Encontrémoslo. Chop-chop!",
  str_homestory_N19chuanshanjia_90010102_1_dialog_content = "¡Oye! Korgon!",
  str_homestory_N19chuanshanjia_90010102_2_dialog_content = "¡Yo! ¡Te estaba buscando, jefe!",
  str_homestory_N19chuanshanjia_90010102_3_dialog_content = "¿Cuántas veces tengo que decirte que dejes de llamarme \"jefe\"?",
  str_homestory_N19chuanshanjia_90010102_4_dialog_content = "¡Decir ah! ¡Buena, jefe! De todos modos, tienes algo bueno <color=#FFB400>madera</color> ¿en tus manos?",
  str_homestory_N19chuanshanjia_90010102_5_dialog_content = "¿Madera?",
  str_homestory_N19chuanshanjia_90010102_6_dialog_content = "Están pensando en construir un pequeño puerto en la isla Sharkfang. De esa manera, no tendrán que seguir arrastrando botes a la orilla todo el tiempo.",
  str_homestory_N19chuanshanjia_90010102_7_dialog_content = "Seguro que estás ocupado. Pero dejemos este asunto de la madera en suspenso por un segundo.",
  str_homestory_N19chuanshanjia_90010102_8_dialog_content = "Quiero presentarte a alguien primero. No es necesario que digas mucho y trata de no asustarlo ni nada.",
  str_homestory_N19chuanshanjia_90010102_9_dialog_content = "¿Conocer a alguien? ¡No es un problema! Pero esta madera no se juntará sola, jefe... Hagámoslo mañana, ¿sí?",
  str_homestory_N19chuanshanjia_90010102_10_dialog_content = "¿Mañana? Eso no servirá, yo...",
  str_homestory_N19chuanshanjia_90010102_11_dialog_content = "Suspiro... Bien, te ayudaré a juntar un poco de leña. ¿Cuánto necesitas?",
  str_homestory_N19chuanshanjia_90010102_12_dialog_content = "<color=#FFB400>10</color> pedazos de ellos deberían hacerlo. Yo también los pagaré, ¡así que no te preocupes!",
  str_homestory_N19chuanshanjia_90010102_13_dialog_content = "¡Inmediatamente!",
  str_homestory_N19chuanshanjia_90010112_1_dialog_content = "10 registros son suficientes.",
  str_homestory_N19chuanshanjia_90010103_1_dialog_content = "¿Reuniste suficiente madera?",
  str_homestory_N19chuanshanjia_90010103_2_dialog_content = "¡Esto debería funcionar! ({1}/{2})",
  str_homestory_N19chuanshanjia_90010103_3_dialog_content = "¡Ese es el jefe para ti! ¡No podría haberlo hecho mejor yo mismo!",
  str_homestory_N19chuanshanjia_90010103_4_dialog_content = "Ahora, cuando lo conozcas, trata de no decir nada extraño. Solo sonríe y asiente la mayor parte del tiempo y estaremos bien.",
  str_homestory_N19chuanshanjia_90010103_5_dialog_content = "¡Sigues hablando de este tipo, pero todavía no me has dicho quién es, jefe! No es una especie de bicho raro, ¿verdad?",
  str_homestory_N19chuanshanjia_90010103_6_dialog_content = "Sabes que no he hablado con ESE tipo de personas en años, jefe...",
  str_homestory_N19chuanshanjia_90010103_7_dialog_content = "Es un animal que habla nuestro idioma, simplemente no lo asustes y estaremos bien.",
  str_homestory_N19chuanshanjia_90010103_8_dialog_content = "Todo lo que digo es que cada vez que abres la boca para hablar, tus dientes afilados como navajas pueden ser un poco... desagradables.",
  str_homestory_N19chuanshanjia_90010103_9_dialog_content = "Sí, sí, capto su idea, jefe.",
  str_homestory_N19chuanshanjia_90010103_10_dialog_content = "Aún no.",
  str_homestory_N19chuanshanjia_90010104_1_dialog_content = "¡Volví!",
  str_homestory_N19chuanshanjia_90010104_2_dialog_content = "¡Oh, gracias a Dios! Me estaba quedando sin cosas de qué hablar. Sigue haciendo todo tipo de preguntas... Casi no puedo mantener la fachada por más tiempo.",
  str_homestory_N19chuanshanjia_90010104_3_dialog_content = "¡Mira, Sahn!",
  str_homestory_N19chuanshanjia_90010104_4_dialog_content = "¡Saludos!",
  str_homestory_N19chuanshanjia_90010104_5_dialog_content = "¡¡H-Él me va a comer vivo!!",
  str_homestory_N19chuanshanjia_90010104_6_dialog_content = "PlayerName... ¡¿Por qué tuviste que traer a ese tipo, de todas las personas?!",
  str_homestory_N19chuanshanjia_90010104_7_dialog_content = "¡¿Qué quieres decir con \"ese tipo\"?!",
  str_homestory_N19chuanshanjia_90010104_8_dialog_content = "¿Olvidaron que soy vegetariano? ¡Lo único que veo cuando miro a un animal pequeño es algo para acariciar y darle golosinas!",
  str_homestory_N19chuanshanjia_90010104_9_dialog_content = "¡No es mi culpa que nací con una gran boca llena de dientes afilados!",
  str_homestory_N19chuanshanjia_90010104_10_dialog_content = "M-Mis disculpas, amigo. Me apresuré a juzgarte por tu apariencia...",
  str_homestory_N19chuanshanjia_90010104_11_dialog_content = "Por aterradora que pueda ser tu sonrisa, debo decir... ¡Tus dientes son algunos de los más brillantes y blancos que he visto en mi vida!",
  str_homestory_N19chuanshanjia_90010104_12_dialog_content = "R-¿En serio? ¡Finalmente, alguien que aprecia mis dientes!",
  str_homestory_N19chuanshanjia_90010104_13_dialog_content = "Mis dientes de tiburón se reemplazan solos a menudo. ¡Puedo triturar mis viejos dientes hasta convertirlos en polvo y regalártelos para que los uses para cocinar!",
  str_homestory_N19chuanshanjia_90010104_14_dialog_content = "E-Eso no será necesario, gracias...",
  str_homestory_N19chuanshanjia_90010104_15_dialog_content = "De todos modos, ¡siéntase libre de visitar Sharkfang Island en cualquier momento!",
  str_homestory_N19chuanshanjia_90010104_16_dialog_content = "El paisaje es el mejor allí, especialmente durante el día, cuando el sol brilla sobre las olas.",
  str_homestory_N19chuanshanjia_90010104_17_dialog_content = "Ah, pero me temo que también debo rechazar su amable invitación. Verá, nuestra especie... son particularmente reacios a las grandes masas de agua.",
  str_homestory_N19chuanshanjia_90010104_18_dialog_content = "Estamos mucho más en casa en las montañas. Si desea visitarnos en el futuro, puede encontrarnos aquí.",
  str_homestory_N19chuanshanjia_90010104_19_dialog_content = "Decidimos venir aquí de visita porque hemos estado demasiado tiempo aislados en las montañas. Mis compañeros de clan querían ver el mundo exterior.",
  str_homestory_N19chuanshanjia_90010104_20_dialog_content = "Solo espero que este lugar sea más pacífico que otros... Mis compañeros de clan y yo hemos soportado tantas dificultades...",
  str_homestory_N19chuanshanjia_90010104_21_dialog_content = "¡Así que es por eso que ustedes siempre han salido corriendo a la primera vista de otras especies!",
  str_homestory_N19chuanshanjia_90010104_22_dialog_content = "Les puedo asegurar que Cloud Gardens es perfectamente seguro.",
  str_homestory_N19chuanshanjia_90010104_23_dialog_content = "¡Entonces regresaré con mis compañeros de clan y les hablaré de este lugar de inmediato!",
  str_homestory_N19chuanshanjia_90010104_24_dialog_content = "¡E-Espera! ¡No llegué a tocar tus escamas!",
  str_homestory_N19chuanshanjia_90010104_25_dialog_content = "Estoy seguro de que tendrás otra oportunidad algún día, Korgon.",
  str_homestory_N19chuanshanjia_90010104_26_dialog_content = "Pero primero, tendrás que guardar esa sonrisa tuya...",
  str_homestory_N19chuanshanjia_90010104_27_dialog_content = "... Realmente no es mi culpa, ya sabes.",
  str_homestory_N19chuanshanjia_90010201_1_dialog_content = "¿Mmm? No eres Sahn, ¿verdad?",
  str_homestory_N19chuanshanjia_90010201_2_dialog_content = "¡Eep! estoy <color=#FFB400>jiji</color>, portador de la diadema más resistente y cómoda de toda la tierra!",
  str_homestory_N19chuanshanjia_90010201_3_dialog_content = "Sahn nos habló de sus formas pacíficas y amistosas, ¡así que vine de inmediato!",
  str_homestory_N19chuanshanjia_90010201_4_dialog_content = "Dime, ¿qué te parece mi diadema? ¡Eep!",
  str_homestory_N19chuanshanjia_90010201_5_option_content = "Es agradable.",
  str_homestory_N19chuanshanjia_90010201_6_dialog_content = "Que tibia respuesta...",
  str_homestory_N19chuanshanjia_90010201_7_option_content = "¡Es fantástico!",
  str_homestory_N19chuanshanjia_90010201_8_dialog_content = "Es muy femenino.",
  str_homestory_N19chuanshanjia_90010201_9_dialog_content = "¡Es mi posesión más preciada! ¡Solo mira esta artesanía! Esta calidad!",
  str_homestory_N19chuanshanjia_90010201_10_dialog_content = "D-De todos modos... Ahora que estás aquí, ¿hay algo en lo que pueda ayudarte?",
  str_homestory_N19chuanshanjia_90010201_11_dialog_content = "¡Eep! ¡Sí, en realidad! ¡Se me ocurrió un chiste nuevo y vine a compartirlo contigo!",
  str_homestory_N19chuanshanjia_90010201_12_dialog_content = "¡Después de todo, soy todo un genio de la comedia entre los Pangalos!",
  str_homestory_N19chuanshanjia_90010201_13_dialog_content = "¡Mi sueño es convertirme en el comediante más grande del mundo, para poder contagiar alegría desenfrenada y risas desgarradoras a todos!",
  str_homestory_N19chuanshanjia_90010201_14_dialog_content = "¿Una broma? Bien, ¡escuchémoslo!",
  str_homestory_N19chuanshanjia_90010201_15_dialog_content = "¡Muy bien entonces! ¡Mantén tus oídos abiertos, prepárate para ello! ¡Eep!",
  str_homestory_N19chuanshanjia_90010201_16_dialog_content = "Hace mucho, mucho tiempo, hubo un valiente guerrero.",
  str_homestory_N19chuanshanjia_90010201_17_dialog_content = "Su espada estaba fría, sus manos estaban frías, su corazón estaba frío, su personalidad era fría como un pepino... De hecho, toda su existencia era fría como el hielo.",
  str_homestory_N19chuanshanjia_90010201_18_dialog_content = "Y al final, se congeló hasta morir.",
  str_homestory_N19chuanshanjia_90010201_19_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_20_dialog_content = "<size=65>Jajajajaja!</size>",
  str_homestory_N19chuanshanjia_90010201_21_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_22_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_23_dialog_content = "<size=65>jajaja</size>",
  str_homestory_N19chuanshanjia_90010201_24_dialog_content = "¡Eep! ¡Tu cara no me engaña! ¡Esa fue la risa más forzada que he escuchado en mi vida!",
  str_homestory_N19chuanshanjia_90010201_25_dialog_content = "Er... ¡E-Eso es porque mi sentido del humor es realmente extraño! ¿Por qué no intentas contarle tu broma a alguien más?",
  str_homestory_N19chuanshanjia_90010201_26_dialog_content = "¡S-Será mejor que no me estés mintiendo!",
  str_homestory_N19chuanshanjia_90010201_27_dialog_content = "¡No lo soy, honesto! creo que recuerdo haber visto Revy por aquí en alguna parte... ¡Perfecto!",
  str_homestory_N19chuanshanjia_90010202_1_dialog_content = "Oye, Revy? Parece que estás distraído.",
  str_homestory_N19chuanshanjia_90010202_2_dialog_content = "Estoy contando las briznas de hierba en el suelo.",
  str_homestory_N19chuanshanjia_90010202_3_dialog_content = "Ya veo... De todos modos, tengo a alguien aquí que quiere contarte un chiste, y creo que realmente lo disfrutarás. ¿Interesado?",
  str_homestory_N19chuanshanjia_90010202_4_dialog_content = "Uh, claro.",
  str_homestory_N19chuanshanjia_90010202_5_dialog_content = "¡Eep! ¡Maravilloso! ¡Parece alguien que puede apreciar un poco de humor seco!",
  str_homestory_N19chuanshanjia_90010202_6_dialog_content = "Estoy escuchando.",
  str_homestory_N19chuanshanjia_90010202_7_dialog_content = "Hace mucho, mucho tiempo, hubo un valiente guerrero.",
  str_homestory_N19chuanshanjia_90010202_8_dialog_content = "Su espada estaba fría, sus manos estaban frías, su corazón estaba frío, su personalidad era fría como un pepino... De hecho, toda su existencia era fría como el hielo.",
  str_homestory_N19chuanshanjia_90010202_9_dialog_content = "Y al final, se congeló hasta morir.",
  str_homestory_N19chuanshanjia_90010202_10_dialog_content = "Oh.",
  str_homestory_N19chuanshanjia_90010202_11_dialog_content = "¡Eep! ¡¿Eso es todo lo que tienes que decir?!",
  str_homestory_N19chuanshanjia_90010202_12_dialog_content = "(¡Mierda! Parece que ni siquiera Revy se reiría de un chiste así...)",
  str_homestory_N19chuanshanjia_90010202_13_dialog_content = "¡Lo siento, Jiji! ¡Déjame ir a buscar a alguien más! Después de todo, Revy estaba ocupado con algo realmente importante en este momento.",
  str_homestory_N19chuanshanjia_90010202_14_dialog_content = "¿No es así, Revy?",
  str_homestory_N19chuanshanjia_90010202_15_dialog_content = "¿Eh?",
  str_homestory_N19chuanshanjia_90010202_16_dialog_content = "¡Vamos! ¡No vayas a ningún lado, Jiji! Encontraré la audiencia perfecta para tu broma, ¡lo prometo!",
  str_homestory_N19chuanshanjia_90010203_1_dialog_content = "¿Eres el único aquí?",
  str_homestory_N19chuanshanjia_90010203_2_dialog_content = "¿Qué significa eso?",
  str_homestory_N19chuanshanjia_90010203_3_dialog_content = "Tú solo... No pareces del tipo que disfruta de las bromas, eso es todo.",
  str_homestory_N19chuanshanjia_90010203_4_dialog_content = "Algo sobre una espada fría y un corazón frío...",
  str_homestory_N19chuanshanjia_90010203_5_dialog_content = "¿Una \"cuchilla fría\"? ¿De qué estás hablando?",
  str_homestory_N19chuanshanjia_90010203_6_dialog_content = "¿Mmm? Dayna!",
  str_homestory_N19chuanshanjia_90010203_7_dialog_content = "¡Jajaja! ¡¿En serio?!",
  str_homestory_N19chuanshanjia_90010203_8_dialog_content = "¿Te estas riendo?",
  str_homestory_N19chuanshanjia_90010203_9_dialog_content = "¿Es esa tu idea de una broma, Boatscrapper?",
  str_homestory_N19chuanshanjia_90010203_10_dialog_content = "N-No, no es mi broma en absoluto. A alguien más se le ocurrió.",
  str_homestory_N19chuanshanjia_90010203_11_dialog_content = "Bueno, llévame a ellos! Ahora estoy libre.",
  str_homestory_N19chuanshanjia_90010211_1_dialog_content = "¡Hazlo, chatarrero!",
  str_homestory_N19chuanshanjia_90010204_1_dialog_content = "¿Su? Pero ella no parece del tipo que entiende los chistes...",
  str_homestory_N19chuanshanjia_90010204_2_dialog_content = "¿Me estás tomando el pelo? ¡Escuché todo tipo de bromas en Umbraton!",
  str_homestory_N19chuanshanjia_90010204_3_dialog_content = "¡Eep! Entonces intentémoslo. ¡Escucha atentamente, ahora!",
  str_homestory_N19chuanshanjia_90010204_4_dialog_content = "Hace mucho, mucho tiempo, hubo un valiente guerrero. Su espada estaba fría...",
  str_homestory_N19chuanshanjia_90010204_5_dialog_content = "Oh ya entiendo.",
  str_homestory_N19chuanshanjia_90010204_6_dialog_content = "No pareces particularmente entusiasta.",
  str_homestory_N19chuanshanjia_90010204_7_dialog_content = "¡No te rindas, Jiji! ¡Sigue adelante!",
  str_homestory_N19chuanshanjia_90010204_8_dialog_content = "Sus manos estaban frías...",
  str_homestory_N19chuanshanjia_90010204_9_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_10_dialog_content = "Su corazón estaba frío.",
  str_homestory_N19chuanshanjia_90010204_10X1_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_10X2_dialog_content = "De hecho, todo su cuerpo estaba frío como el hielo.",
  str_homestory_N19chuanshanjia_90010204_10X3_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_11_dialog_content = "... Pffff.",
  str_homestory_N19chuanshanjia_90010204_12_dialog_content = "Y al final, se congeló hasta morir.",
  str_homestory_N19chuanshanjia_90010204_13_dialog_content = "<size=65>Jajajajaja! ¡Esa broma fue completamente seca!</size>",
  str_homestory_N19chuanshanjia_90010204_14_dialog_content = "<size=65>¿¡¿Qué?!?</size>",
  str_homestory_N19chuanshanjia_90010204_15_dialog_content = "Su entrega podría usar algo de trabajo, ¡pero la broma fue sólida como una roca! ¡Necesitaba una buena risa!",
  str_homestory_N19chuanshanjia_90010204_16_dialog_content = "¡Me alegro de que alguien finalmente haya encontrado el humor en él!",
  str_homestory_N19chuanshanjia_90010204_17_dialog_content = "¡Con bromas como esa, podrías ganar algunos fanáticos en Umbraton!",
  str_homestory_N19chuanshanjia_90010204_18_dialog_content = "Probablemente incluso te harías famoso.",
  str_homestory_N19chuanshanjia_90010204_19_dialog_content = "¡¡¡Eep!!! R-¿En serio? ¡Debería ir a decírselo a mis compañeros de clan!",
  str_homestory_N19chuanshanjia_90010204_20_dialog_content = "Jajajajaja! ¡Esa broma fue tan seca! ¡Y tan divertido!",
  str_homestory_N19chuanshanjia_90010204_21_dialog_content = "debería preguntar PlayerName para contarlo de nuevo cuando tenga la oportunidad.",
  str_homestory_N19chuanshanjia_90010301_1_dialog_content = "<size=65>¡Guau! ¡Finalmente le encontré!</size>",
  str_homestory_N19chuanshanjia_90010301_2_dialog_content = "Otro Pangalo, ¿eh? Y este no parece muy feliz... ¿Eres amigo de Sahn y Jiji, por casualidad?",
  str_homestory_N19chuanshanjia_90010301_3_dialog_content = "¡Guau! Usted debe ser PlayerName! soy <color=#FFB400>Rechoncho</color>, y he venido en busca de venganza!",
  str_homestory_N19chuanshanjia_90010301_4_dialog_content = "¡Por tu culpa, Jiji me hizo rodar y me pateó como una pelota!",
  str_homestory_N19chuanshanjia_90010301_5_dialog_content = "E-Espera, ¿entonces no deberías vengarte de Jiji, no de mí?",
  str_homestory_N19chuanshanjia_90010301_6_dialog_content = "¡Guau! ¡Dijo que solo lo hizo porque le mentiste!",
  str_homestory_N19chuanshanjia_90010301_7_dialog_content = "Jiji vino corriendo hacia mí, diciendo algo sobre una \"cuchilla fría\" y \"manos frías\"...",
  str_homestory_N19chuanshanjia_90010301_8_dialog_content = "\"Y luego murió congelada\".",
  str_homestory_N19chuanshanjia_90010301_9_dialog_content = "¡Guau! ¡Exactamente! Que broma tan poco graciosa.",
  str_homestory_N19chuanshanjia_90010301_10_dialog_content = "¡Pero ella siguió insistiendo en que era la broma más divertida del mundo y que tú lo habías comprobado!",
  str_homestory_N19chuanshanjia_90010301_11_dialog_content = "¡Se puso furiosa cuando descubrió que en realidad era una broma horrible y que le mentiste al respecto!",
  str_homestory_N19chuanshanjia_90010301_12_dialog_content = "Y luego me convirtió en una pelota pateadora.",
  str_homestory_N19chuanshanjia_90010301_13_dialog_content = "Me pateó durante tanto tiempo que el mundo sigue girando ante mis ojos.",
  str_homestory_N19chuanshanjia_90010301_14_dialog_content = "Así que pensé para mis adentros, si fuiste tú quien comenzó todo esto... ¡Entonces deberías ser tú quien fuera castigado, no yo!",
  str_homestory_N19chuanshanjia_90010301_15_dialog_content = "P-Castigo?",
  str_homestory_N19chuanshanjia_90010301_16_dialog_content = "¡Guau! ¡Así es! ¡Deberías hacerte un ovillo y dejar que ella te patee!",
  str_homestory_N19chuanshanjia_90010301_17_dialog_content = "¿Q-Qué clase de lógica es esa...?",
  str_homestory_N19chuanshanjia_90010301_18_dialog_content = "Bueno, ¿tienes alguna idea mejor?",
  str_homestory_N19chuanshanjia_90010301_19_dialog_content = "Si tan solo hubieras sido honesto con Jiji sobre su broma desde el principio, nada de esto estaría sucediendo.",
  str_homestory_N19chuanshanjia_90010301_20_dialog_content = "P-Pero cada uno tiene su propio sentido del humor...",
  str_homestory_N19chuanshanjia_90010301_21_dialog_content = "¡Creo que animar a Jiji es importante!",
  str_homestory_N19chuanshanjia_90010301_22_dialog_content = "Puede que no haya sido tan divertido como ella esperaba, pero a veces una pequeña mentira piadosa... Quiero decir, ¡todavía era bastante divertido! ¡Y Jiji necesita nuestro apoyo!",
  str_homestory_N19chuanshanjia_90010301_23_dialog_content = "Jiji? ¡Gwaaa! ¡¿Qué hay de mí?! ¡Solo mira la forma en la que estoy!",
  str_homestory_N19chuanshanjia_90010301_24_dialog_content = "¡Llevo tanto tiempo acurrucado que ya no puedo enderezar la espalda!",
  str_homestory_N19chuanshanjia_90010301_25_dialog_content = "¡Lo que necesito es algo de alimentación!",
  str_homestory_N19chuanshanjia_90010301_26_dialog_content = "\"Alimentación\"...? ¿Quieres decir comida?",
  str_homestory_N19chuanshanjia_90010301_27_dialog_content = "¡Correcto! Alguna cosa <color=#FFB400>dulce</color> funcionaría mejor, creo.",
  str_homestory_N19chuanshanjia_90010301_28_dialog_content = "Postres, ¿eh? Creo que vi un <color=#FFB400>Comerciante Chubb</color> yendo hacia el bosque... Echémosle un vistazo.",
  str_homestory_N19chuanshanjia_90010311_1_dialog_content = "Encontrarás algo dulce, ¿verdad?",
  str_homestory_N19chuanshanjia_90010302_1_dialog_content = "postres? Completamente. Cachero.",
  str_homestory_N19chuanshanjia_90010302_2_dialog_content = "¿Completamente?",
  str_homestory_N19chuanshanjia_90010302_3_dialog_content = "¡Esta no es una ventanilla única para todas sus necesidades de bocadillos! ¡Tienes que hacer un pedido primero! ¡Cachero!",
  str_homestory_N19chuanshanjia_90010302_4_dialog_content = "¿Hacer un pedido...?",
  str_homestory_N19chuanshanjia_90010302_5_dialog_content = "¡Cachero! ¡Así es! ¿Ver? <color=#FFB400>Vice</color> tiene un pedido de un pastel aquí mismo!",
  str_homestory_N19chuanshanjia_90010302_6_dialog_content = "Vice! ¡Por supuesto! ¿Sabes donde esta ella?",
  str_homestory_N19chuanshanjia_90010302_7_dialog_content = "Por el rio. ¡Cachero!",
  str_homestory_N19chuanshanjia_90010302_8_dialog_content = "¡Gracias! ¡Cachero!",
  str_homestory_N19chuanshanjia_90010302_9_dialog_content = "¡No lo menciones! ¡Cachero!",
  str_homestory_N19chuanshanjia_90010302_10_dialog_content = "¿Eh?",
  str_homestory_N19chuanshanjia_90010312_1_dialog_content = "Por el rio. Vice, Chub.",
  str_homestory_N19chuanshanjia_90010303_1_dialog_content = "Oye, Vice? ¿Qué es eso en tu cara...?",
  str_homestory_N19chuanshanjia_90010303_2_dialog_content = "¿Eh?",
  str_homestory_N19chuanshanjia_90010303_3_dialog_content = "No estabas comiendo pastel hace un momento, ¿verdad?",
  str_homestory_N19chuanshanjia_90010303_4_dialog_content = "¿Cómo lo supiste?",
  str_homestory_N19chuanshanjia_90010303_5_dialog_content = "¡Argh, llegué demasiado tarde!",
  str_homestory_N19chuanshanjia_90010303_6_dialog_content = "Culpable de los cargos, jeje... ¿De verdad querías tanto un pastel?",
  str_homestory_N19chuanshanjia_90010303_7_dialog_content = "Es una larga historia... Solo necesito un poco de pastel ahora mismo, aunque sea un trozo pequeño.",
  str_homestory_N19chuanshanjia_90010303_8_dialog_content = "Cuando fui a recoger mi pastel, vi <color=#FFB400>Korgon</color> haciendo un pedido para algunos, también. Aunque no tengo ni idea de para qué...",
  str_homestory_N19chuanshanjia_90010303_9_dialog_content = "Pero lo vi dirigiéndose a <color=#FFB400>Plaza Jacinto</color> después.",
  str_homestory_N19chuanshanjia_90010303_10_dialog_content = "Plaza Jacinto, ¿eh? ¡Entiendo!",
  str_homestory_N19chuanshanjia_90010313_1_dialog_content = "¡Date prisa ahora! ¡O terminará de comérselo!",
  str_homestory_N19chuanshanjia_90010304_1_dialog_content = "¡Oye! ¡Finalmente le encontré!",
  str_homestory_N19chuanshanjia_90010304_2_dialog_content = "¿Qué pasa, jefe?",
  str_homestory_N19chuanshanjia_90010304_3_dialog_content = "¿Aún te queda pastel?",
  str_homestory_N19chuanshanjia_90010304_4_dialog_content = "¿Vaya? ¿No sabía que te gustaban los dulces, jefe?",
  str_homestory_N19chuanshanjia_90010304_5_dialog_content = "¡Ay! Sí, lo hice.",
  str_homestory_N19chuanshanjia_90010304_6_dialog_content = "¿Eh? No, eso no puede ser correcto. Recuerdo que me dijiste que no te importan los dulces.",
  str_homestory_N19chuanshanjia_90010304_7_dialog_content = "Tienes razón, pero... Es una especie de larga historia.",
  str_homestory_N19chuanshanjia_90010304_8_dialog_content = "¡No se preocupe, jefe! ¡Entiendo perfectamente! Cada hombre tiene sus propios secretos...",
  str_homestory_N19chuanshanjia_90010304_9_dialog_content = "Y si mi corazonada es correcta... Diría que tienes una pequeña criatura que alimentar, ¿no?",
  str_homestory_N19chuanshanjia_90010304_10_dialog_content = "¿E-Eh? Er, quiero decir... Sí, sí, lo hago...",
  str_homestory_N19chuanshanjia_90010304_11_dialog_content = "De todos modos, ¿crees que podrías prescindir de un pedacito de pastel...?",
  str_homestory_N19chuanshanjia_90010304_12_dialog_content = "¡No hay problema!",
  str_homestory_N19chuanshanjia_90010314_1_dialog_content = "No es mucho, pero debería ser suficiente. ¿Qué dices, jefe?",
  str_homestory_N19chuanshanjia_90010305_1_dialog_content = "¡Ya estoy de vuelta! ¡Y traje pastel!",
  str_homestory_N19chuanshanjia_90010305_2_dialog_content = "¡Espera!",
  str_homestory_N19chuanshanjia_90010305_3_dialog_content = "¿Qué tal?",
  str_homestory_N19chuanshanjia_90010305_4_dialog_content = "Este pastel no ha sido correctamente <color=#FFB400>sazonado</color>, lo tiene?",
  str_homestory_N19chuanshanjia_90010305_5_dialog_content = "\"Sazonado\"...?",
  str_homestory_N19chuanshanjia_90010305_6_dialog_content = "Si bien la dulzura de un pastel suele ser el sabor principal, ¡hay otro condimento que es igual de importante!",
  str_homestory_N19chuanshanjia_90010305_7_dialog_content = "¿De qué tipo de condimento estás hablando? No creo que sea fácil encontrar ingredientes preparados aquí...",
  str_homestory_N19chuanshanjia_90010305_8_dialog_content = "¡No hay necesidad, tenemos mucho aquí!",
  str_homestory_N19chuanshanjia_90010305_9_dialog_content = "¿Aqui donde?",
  str_homestory_N19chuanshanjia_90010305_10_dialog_content = "El suelo debajo de nosotros, por supuesto.",
  str_homestory_N19chuanshanjia_90010305_11_dialog_content = "¡¿S-Suelo...?!",
  str_homestory_N19chuanshanjia_90010305_12_dialog_content = "Los de nuestra especie excavan montañas día tras día y, a menudo, terminan consumiendo tierra en el proceso.",
  str_homestory_N19chuanshanjia_90010305_13_dialog_content = "Y, por supuesto, diferentes tipos de suelo tienen diferentes sabores. Personalmente, me gusta agregar una cucharada de tierra herbosa a mi comida para darle un sabor ligeramente astringente. ¡Es el mejor!",
  str_homestory_N19chuanshanjia_90010305_14_dialog_content = "Ah, solo pensar en agregarle un poco a ese pedazo de pastel... ¡Ya se me está haciendo la boca agua!",
  str_homestory_N19chuanshanjia_90010305_15_dialog_content = "El mundo puede ser un lugar realmente extraño a veces...",
  str_homestory_N19chuanshanjia_90010305_16_dialog_content = "En cualquier caso, ¡tienes mi agradecimiento! Ahora bien, voy a buscar tierra adecuada para este pastel, ¡así puedo compartir un poco con Jiji como ofrenda de paz!",
  str_homestory_N19chuanshanjia_90010305_17_dialog_content = "¡Quizás entonces podría convencerla de que me libre de más castigos! ¡Guau!",
  str_homestory_N19chuanshanjia_90010305_18_dialog_content = "Qué conjunto de gustos completamente diferente... Aunque supongo que hay un pastel para todos, ¿eh?",
  str_homestory_N19chuanshanjia_90010401_1_dialog_content = "¡Escuché que venciste a Tubby! ¡Golpéalo bien, escuché!",
  str_homestory_N19chuanshanjia_90010401_2_dialog_content = "¿Seguro que tenéis talento para malinterpretar a los demás...?",
  str_homestory_N19chuanshanjia_90010401_3_dialog_content = "Za! ¡Tubby se fue furioso hace unos días, diciendo que iba a ajustar cuentas contigo! ¡Ajustar cuentas!",
  str_homestory_N19chuanshanjia_90010401_4_dialog_content = "¡Pero luego volvió feliz y despreocupado! ¡Dijo que no hizo nada! ¡Ni una sola cosa!",
  str_homestory_N19chuanshanjia_90010401_5_dialog_content = "¡Debes haberlo golpeado tonto! ¡Golpéale los sesos, ¿no?!",
  str_homestory_N19chuanshanjia_90010401_6_dialog_content = "¡Yo no hice nada de eso! ¡Acabo de compartir un pedazo de pastel con Tubby, eso es todo!",
  str_homestory_N19chuanshanjia_90010401_7_dialog_content = "Za! ¡Debes ser todo un luchador! ¡Un guerrero habilidoso, de hecho!",
  str_homestory_N19chuanshanjia_90010401_8_dialog_content = "estoy <color=#FFB400>Exigente</color>. ¡Como guerrero de Lithic Pangalos, te desafío a la batalla! ¡A la batalla!",
  str_homestory_N19chuanshanjia_90010401_9_dialog_content = "Ustedes no escuchan mucho lo que dicen los demás, ¿verdad...?",
  str_homestory_N19chuanshanjia_90010401_10_dialog_content = "Siento decepcionarte, quisquilloso, pero no soy un luchador en lo más mínimo. Tendrás que luchar con alguien más.",
  str_homestory_N19chuanshanjia_90010401_11_dialog_content = "¿Za? ¿No quieres pelear conmigo?",
  str_homestory_N19chuanshanjia_90010401_12_dialog_content = "¿Podría ser... que eres tan poderoso que eres incapaz de contener tu inmenso poder? ¿Que temes que pelear conmigo resultará en mi espantosa muerte?",
  str_homestory_N19chuanshanjia_90010401_13_dialog_content = "Si es así... ¡entonces envía a tu discípulo más fuerte a la batalla! ¡¡Tu mejor discípula!! Za!!!",
  str_homestory_N19chuanshanjia_90010401_14_dialog_content = "¿D-discípulo...?",
  str_homestory_N19chuanshanjia_90010401_15_dialog_content = "¡Sí! Si no luchas conmigo por miedo a hacerme daño, ¡entonces permite que tu discípulo pelee en tu lugar! Za!",
  str_homestory_N19chuanshanjia_90010401_16_dialog_content = "¡Ustedes REALMENTE no escuchan lo que otros dicen, en absoluto!",
  str_homestory_N19chuanshanjia_90010401_17_dialog_content = "¡Disparates! Te escuché alto y claro. ¡Ahora envía por tu discípulo más fuerte! ¡Esperaré aquí con ansiosa anticipación de nuestra próxima batalla!",
  str_homestory_N19chuanshanjia_90010401_18_dialog_content = "Está bien.",
  str_homestory_N19chuanshanjia_90010401_19_dialog_content = "Parece que tengo otro malentendido entre manos... Supongo que tendré que ir a buscar a alguien que se encargue de esto.",
  str_homestory_N19chuanshanjia_90010401_20_dialog_content = "Za! ¿De qué diablos estás murmurando? ¡Dimelo ahora!",
  str_homestory_N19chuanshanjia_90010401_21_dialog_content = "Dije que iba a dar un paseo por la orilla del río. Volveré en un momento.",
  str_homestory_N19chuanshanjia_90010402_1_dialog_content = "¿Qué estás mirando? Cachero.",
  str_homestory_N19chuanshanjia_90010402_2_dialog_content = "Suspiro... Te ves tan luchador como yo...",
  str_homestory_N19chuanshanjia_90010402_3_dialog_content = "Los Chubbs no estamos hechos para pelear, no. Cachero.",
  str_homestory_N19chuanshanjia_90010402_4_dialog_content = "Este es un lugar de paz, después de todo. Cachero.",
  str_homestory_N19chuanshanjia_90010402_5_dialog_content = "hola... es eso Barton? ¿Qué está haciendo aquí? ¡Cachero!",
  str_homestory_N19chuanshanjia_90010402_6_dialog_content = "Está examinando el terreno en busca de un lugar para construir un campo de entrenamiento para los nuevos reclutas. ¡Cachero!",
  str_homestory_N19chuanshanjia_90010402_7_dialog_content = "¡Realmente es él!",
  str_homestory_N19chuanshanjia_90010402_8_dialog_content = "¿Ch-Chubb?",
  str_homestory_N19chuanshanjia_90010411_1_dialog_content = "Cercano. Barton, Chub.",
  str_homestory_N19chuanshanjia_90010403_1_dialog_content = "Podemos compactar la tierra aquí para campos de entrenamiento y poner los cimientos para un cuartel allá...",
  str_homestory_N19chuanshanjia_90010403_2_dialog_content = "Ahí tienes, Barton!",
  str_homestory_N19chuanshanjia_90010403_3_dialog_content = "¡Ah, tu momento no podría ser mejor! ¡Necesito tu ayuda con algo, y tendré que apoderarme de esta tierra para hacerlo!",
  str_homestory_N19chuanshanjia_90010403_4_dialog_content = "C-Comandante..?",
  str_homestory_N19chuanshanjia_90010403_5_dialog_content = "¡Es demasiado pacífico aquí, lo que simplemente no es suficiente!",
  str_homestory_N19chuanshanjia_90010403_6_dialog_content = "¡Todos ustedes son como corderos sentados en una guarida de lobos!",
  str_homestory_N19chuanshanjia_90010403_7_dialog_content = "¡Necesitas guardias! ¡Necesitas soldados!",
  str_homestory_N19chuanshanjia_90010403_8_dialog_content = "Entonces, naturalmente, lo primero y más importante es un campo de entrenamiento.",
  str_homestory_N19chuanshanjia_90010403_9_dialog_content = "¡Déjamelo a mí! ¡Estableceré este regimiento y también los entrenaré!",
  str_homestory_N19chuanshanjia_90010403_10_dialog_content = "Y créeme, ¡no descansaré hasta que termine el trabajo! De esa manera, los números de mi propia legión también podrían aumentar...",
  str_homestory_N19chuanshanjia_90010403_11_dialog_content = "Estoy bastante seguro de que esa es la única razón por la que estás haciendo esto...",
  str_homestory_N19chuanshanjia_90010403_12_dialog_content = "No importa, ahora no es el momento de preguntar sobre eso.",
  str_homestory_N19chuanshanjia_90010403_13_dialog_content = "¿Crees que tu campamento puede esperar un poco más, Barton? Tengo a alguien aquí que quiere probar su temple contra ti.",
  str_homestory_N19chuanshanjia_90010403_14_dialog_content = "Un nuevo recluta ya ha llamado a la puerta, ¿eh?",
  str_homestory_N19chuanshanjia_90010403_15_dialog_content = "¿Dónde están?",
  str_homestory_N19chuanshanjia_90010403_16_dialog_content = "Justo allí.",
  str_homestory_N19chuanshanjia_90010403_17_dialog_content = "Muy bien, ¡es hora de una lección de humildad! Tal vez entonces se lo piensen dos veces antes de desafiar al instructor en su primer día...",
  str_homestory_N19chuanshanjia_90010403_18_dialog_content = "E-Espera, Barton! ¡Aún tengo más que contarte!",
  str_homestory_N19chuanshanjia_90010412_1_dialog_content = "Por qué sigues aquí?",
  str_homestory_N19chuanshanjia_90010404_1_dialog_content = "Así que eres el pequeño advenedizo que intenta causarnos problemas, ¿verdad?",
  str_homestory_N19chuanshanjia_90010404_2_dialog_content = "Za! Eres aún más arrogante que PlayerName! ¡Mucho más arrogante!",
  str_homestory_N19chuanshanjia_90010404_3_dialog_content = "Supongo que también eres un hábil luchador, ¿no? Za!",
  str_homestory_N19chuanshanjia_90010404_4_dialog_content = "¡Ya tienen ganas de pelear! Prácticamente puedo ver las chispas volando...",
  str_homestory_N19chuanshanjia_90010404_5_dialog_content = "¡No necesito ser un luchador hábil para poner a un recluta insubordinado en su lugar!",
  str_homestory_N19chuanshanjia_90010404_6_dialog_content = "No pareces un gran luchador. Pero hay muchos bichos raros como tú aquí en los Jardines de las Nubes.",
  str_homestory_N19chuanshanjia_90010404_7_dialog_content = "¡Al diablo con eso! Si tus brazos y piernas funcionan bien, y esa cola tuya no es solo para mostrar, ¡entonces te convertiré en un soldado!",
  str_homestory_N19chuanshanjia_90010404_8_dialog_content = "Ahora, entonces, ¡que comience el entrenamiento!",
  str_homestory_N19chuanshanjia_90010404_9_dialog_content = "¡Como se esperaba de un verdadero discípulo del maestro! ¡La dureza de tus palabras es tan poderosa como la confianza que emanas!",
  str_homestory_N19chuanshanjia_90010404_10_dialog_content = "¡Pero aún así, me subestimas bajo tu propio riesgo! ¡Ha llegado el momento de decidir quién de nosotros es más fuerte! ¡Zaaa!",
  str_homestory_N19chuanshanjia_90010404_11_dialog_content = "<size=65>¡Espera!</size>",
  str_homestory_N19chuanshanjia_90010404_12_dialog_content = "¡N-no creo que una batalla sea la forma correcta de hacer esto! ¿Por qué ustedes dos no...",
  str_homestory_N19chuanshanjia_90010404_13_dialog_content = "Tener un concurso de \"<color=#FFB400>auras</color>,\" ¿en cambio?",
  str_homestory_N19chuanshanjia_90010404_14_dialog_content = "... Za? ¿\"Auras\"?",
  str_homestory_N19chuanshanjia_90010404_15_dialog_content = "¿Nuestras auras?",
  str_homestory_N19chuanshanjia_90010404_16_dialog_content = "Es como... Una combinación de tu voluntad de luchar, tu estado físico y tus capacidades de combate, entre otras cosas.",
  str_homestory_N19chuanshanjia_90010404_17_dialog_content = "Soy Caelestita, ¿recuerdas? Puedo usar mis poderes para ver sus auras y determinar cuál de ustedes es más fuerte.",
  str_homestory_N19chuanshanjia_90010404_18_dialog_content = "¡¿E-Es eso posible?!",
  str_homestory_N19chuanshanjia_90010404_19_dialog_content = "Es... Puedo dar fe de la fuerza de los poderes psíquicos de Caelestites. Este método debería funcionar tan bien como una batalla real.",
  str_homestory_N19chuanshanjia_90010404_20_dialog_content = "Comencemos.",
  str_homestory_N19chuanshanjia_90010404_21_dialog_content = "<anim type=Shake><size=65>Grrrrrr—</size></anim>",
  str_homestory_N19chuanshanjia_90010404_22_dialog_content = "<anim type=Shake><size=65>Zaaaaa—</size></anim>",
  str_homestory_N19chuanshanjia_90010404_23_dialog_content = "¡¿Q-Qué son estos?! ¡No puedo decir cuál es más fuerte!",
  str_homestory_N19chuanshanjia_90010404_24_dialog_content = "¡Ambos son increíblemente poderosos!",
  str_homestory_N19chuanshanjia_90010404_25_dialog_content = "¡Ya veo!",
  str_homestory_N19chuanshanjia_90010404_26_dialog_content = "¡Impresionante!",
  str_homestory_N19chuanshanjia_90010404_27_dialog_content = "Me pareció un empate, muchachos.",
  str_homestory_N19chuanshanjia_90010404_28_dialog_content = "(Otro Pangalo, otra mentira...)",
  str_homestory_N19chuanshanjia_90010404_29_dialog_content = "Tengo que decir, PlayerName¡Hiciste bien en encontrar un nuevo recluta tan prometedor! ¡Tienes mi agradecimiento!",
  str_homestory_N19chuanshanjia_90010404_30_dialog_content = "Illumina podría usar a alguien como tú, ¡y nunca te faltará nada bajo mi liderazgo! ¿Qué dices, mi amigo?",
  str_homestory_N19chuanshanjia_90010404_31_dialog_content = "Za! Un discípulo con sus propios discípulos... ¡Verdaderamente, estoy en presencia de maestros!",
  str_homestory_N19chuanshanjia_90010404_32_dialog_content = "¡Debo volver a las montañas y entrenar durante muchos años más, si quiero alcanzar tales alturas también! ¡Hasta la próxima, compañeros guerreros! ¡Despedida!",
  str_homestory_N19chuanshanjia_90010404_33_dialog_content = "¡Y también mostró tanta promesa! Un día triste para el ejército de Illumina, de hecho...",
  str_homestory_N19chuanshanjia_90010404_34_dialog_content = "¡Una vez que mi campo de entrenamiento esté construido, me aseguraré de reclutarla en mis filas! Hasta la proxima vez, PlayerName!",
  str_homestory_N19chuanshanjia_90010404_35_dialog_content = "No puedo creerlo... Terminaron admirando las fortalezas del otro...",
  str_homestory_N19chuanshanjia_90010501_1_dialog_content = "¡Mi amigo!",
  str_homestory_N19chuanshanjia_90010501_2_dialog_content = "¿Eh? ¿Estás hablando conmigo?",
  str_homestory_N19chuanshanjia_90010501_3_dialog_content = "Du-du! Todos hablaron de tu ayuda, ¡así que vine a verte también!",
  str_homestory_N19chuanshanjia_90010501_4_dialog_content = "Déjame adivinar... Tu nombre es \"Du-Du\" o algo así, ¿verdad?",
  str_homestory_N19chuanshanjia_90010501_5_dialog_content = "en realidad es <color=#FFB400>panzaverde</color>! Du-du!",
  str_homestory_N19chuanshanjia_90010501_6_dialog_content = "Ya veo... Cuando dijiste \"todos\", ¿te referías a todos los Pangalos que vinieron en los últimos días?",
  str_homestory_N19chuanshanjia_90010501_7_dialog_content = "¡Por cierto! Todos sienten un gran sentimiento de gratitud hacia ti, ¡así que vine a entregar una muestra de esa gratitud!",
  str_homestory_N19chuanshanjia_90010501_8_dialog_content = "¿Una muestra de gratitud? ¿Como un regalo?",
  str_homestory_N19chuanshanjia_90010501_9_dialog_content = "Du-du! ¡Una bebida especial, para ser precisos! ¡Hecho de una receta familiar secreta!",
  str_homestory_N19chuanshanjia_90010501_10_dialog_content = "Puede parecer normal por fuera...",
  str_homestory_N19chuanshanjia_90010501_11_dialog_content = "¡Pero entenderás lo especial que es el momento en que pasa por tus labios! Du-du!",
  str_homestory_N19chuanshanjia_90010501_12_dialog_content = "Se siente un poco cálido a medida que baja por la garganta, pero una vez que llega a la barriga, todo el cuerpo experimentará una sensación de comodidad como nunca antes había sentido...",
  str_homestory_N19chuanshanjia_90010501_13_dialog_content = "¡Suena bastante interesante! ¿Existe realmente tal bebida en el mundo?",
  str_homestory_N19chuanshanjia_90010501_14_dialog_content = "Du-du! ¡Por supuesto que lo hay! Ahora bien, ¿te gustaría probar algunos?",
  str_homestory_N19chuanshanjia_90010501_15_dialog_content = "¡Por supuesto! ¿Qué necesitas para hacerlo?",
  str_homestory_N19chuanshanjia_90010501_16_dialog_content = "Du-du! Como dije, ¡es una receta familiar secreta!",
  str_homestory_N19chuanshanjia_90010501_17_dialog_content = "Primero, necesitaré algunos <color=#FFB400>sal</color>.",
  str_homestory_N19chuanshanjia_90010501_18_dialog_content = "Creo que vi el <color=#FFB400>Comerciante Chubb</color> deambulando cerca del bosque. ¡Podemos pedir algunos!",
  str_homestory_N19chuanshanjia_90010511_1_dialog_content = "El reloj está corriendo. ¡Apresúrate! Du-du.",
  str_homestory_N19chuanshanjia_90010502_1_dialog_content = "¿Sal? Sí, tengo un poco. ¡Cachero!",
  str_homestory_N19chuanshanjia_90010502_2_dialog_content = "Alguien ya ha hecho pedidos de sal. No puedo venderlo como quisiera, Chubb.",
  str_homestory_N19chuanshanjia_90010502_3_dialog_content = "Solo necesito un poquito. ¿No puedes prescindir de un poco?",
  str_homestory_N19chuanshanjia_90010502_4_dialog_content = "Déjame ver, Chubb.",
  str_homestory_N19chuanshanjia_90010502_5_dialog_content = "Debería estar bien conseguirte un poco, según mi estimación. ¡Cachero!",
  str_homestory_N19chuanshanjia_90010502_6_dialog_content = "¡Eso es genial!",
  str_homestory_N19chuanshanjia_90010502_7_dialog_content = "Pero debes compensar la diferencia con <color=#FFB400>mineral</color>. ¡Necesito aumentar las ventas del mineral, Chubb!",
  str_homestory_N19chuanshanjia_90010502_8_dialog_content = "¡No es un problema! ¡Podemos negociar!",
  str_homestory_N19chuanshanjia_90010512_1_dialog_content = "Dije 10! ¡Cachero!",
  str_homestory_N19chuanshanjia_90010503_1_dialog_content = "¿Suficiente mineral?",
  str_homestory_N19chuanshanjia_90010503_2_dialog_content = "¡Aquí! los minerales. ({1}/{2})",
  str_homestory_N19chuanshanjia_90010503_3_dialog_content = "¡Eso fue rápido! ¡Cachero!",
  str_homestory_N19chuanshanjia_90010503_4_dialog_content = "¡Por supuesto! PlayerName está muy familiarizado con los Jardines de Nubes! ¡Cachero!",
  str_homestory_N19chuanshanjia_90010503_5_dialog_content = "Esta es la sal. No lo pierdas. Cachero.",
  str_homestory_N19chuanshanjia_90010503_6_dialog_content = "Todo embalado apretada y firmemente. No lo tires en el camino de regreso, Chubb.",
  str_homestory_N19chuanshanjia_90010503_7_dialog_content = "¡Muchas gracias!",
  str_homestory_N19chuanshanjia_90010503_8_dialog_content = "Aún no.",
  str_homestory_N19chuanshanjia_90010513_1_dialog_content = "¡Ten cuidado de no derramarlo, Chubb!",
  str_homestory_N19chuanshanjia_90010504_1_dialog_content = "Aquí está la sal.",
  str_homestory_N19chuanshanjia_90010504_2_dialog_content = "¡Eso llevó mucho tiempo! Du-du!",
  str_homestory_N19chuanshanjia_90010504_3_dialog_content = "Sí, eso fue un gran desvío. Si no fuera por esta misteriosa bebida...",
  str_homestory_N19chuanshanjia_90010504_4_dialog_content = "Lo verás pronto. ¡Tengo el resto de los ingredientes listos para usar, du-du!",
  str_homestory_N19chuanshanjia_90010504_5_dialog_content = "¡Vamos a ponerlo en marcha!",
  str_homestory_N19chuanshanjia_90010504_6_dialog_content = "Te vas a ir de aquí por un segundo. Esta es una receta secreta, ¿sabes? ¡Exclusivo! Du-du!",
  str_homestory_N19chuanshanjia_90010504_7_dialog_content = "Oh, entonces déjame <color=#FFB400>ir a caminar por algún lugar cercano</color>.",
  str_homestory_N19chuanshanjia_90010504_8_dialog_content = "¡Ve a dar un paseo más largo! ¡Junto a la orilla del río está bien!",
  str_homestory_N19chuanshanjia_90010505_1_dialog_content = "¡Por fin estás aquí! ¡La bebida está lista!",
  str_homestory_N19chuanshanjia_90010505_2_dialog_content = "¿Eh? Se ve muy normal. Es transparente y además no huele a nada.",
  str_homestory_N19chuanshanjia_90010505_3_dialog_content = "¡Le agregué un sabor secreto! ¡Un tipo especial! No se puede ver cuando se pone en agua.",
  str_homestory_N19chuanshanjia_90010505_4_dialog_content = "Un sabor que no se ve en el agua... ¿Es esa bolsa de sal?",
  str_homestory_N19chuanshanjia_90010505_5_dialog_content = "¡Me gusta la gente inteligente! Du-du!",
  str_homestory_N19chuanshanjia_90010505_6_dialog_content = "¡Ay! ¡Oh no, ya no es un secreto!",
  str_homestory_N19chuanshanjia_90010505_7_dialog_content = "¿Me estás diciendo que el único sabor en esta bebida misteriosa es la sal?",
  str_homestory_N19chuanshanjia_90010505_8_dialog_content = "Tu habilidad psíquica está a la altura de lo que me decía Fussy. Du-du!",
  str_homestory_N19chuanshanjia_90010505_9_dialog_content = "De hecho, solo sal. Du-du.",
  str_homestory_N19chuanshanjia_90010505_10_dialog_content = "<size=65>¿No es simplemente agua salada entonces?</size>",
  str_homestory_N19chuanshanjia_90010505_11_dialog_content = "¡Shh! ¡Que nadie escuche eso! Du-du!",
  str_homestory_N19chuanshanjia_90010505_12_dialog_content = "¡Si es sal, hay mucha junto al mar!",
  str_homestory_N19chuanshanjia_90010505_13_dialog_content = "¡Pero no hay ninguno en las montañas! Du-du! Todo lo que encuentras en las montañas es el tipo de agua que es clara y no tiene sabor.",
  str_homestory_N19chuanshanjia_90010505_14_dialog_content = "Una vez, estaba en una cueva y lamí el agua condensada en la roca. estaba salado",
  str_homestory_N19chuanshanjia_90010505_15_dialog_content = "¡Encontré este sabor maravilloso desde entonces! Du-du!",
  str_homestory_N19chuanshanjia_90010505_16_dialog_content = "(Bueno, la sal es algo común en nuestras vidas).",
  str_homestory_N19chuanshanjia_90010505_17_dialog_content = "(Pero para ellos...)",
  str_homestory_N19chuanshanjia_90010505_18_dialog_content = "Ahora que lo mencionas, yo también me doy cuenta.",
  str_homestory_N19chuanshanjia_90010505_19_dialog_content = "La sal tiene un sabor verdaderamente maravilloso.",
  str_homestory_N19chuanshanjia_90010505_20_dialog_content = "¡Cuéntame sobre eso! ¡Yo! Du-du! ¡Debes mantenerlo en secreto!",
  str_homestory_N19chuanshanjia_90010505_21_dialog_content = "Bien bien.",
  str_homestory_N19chuanshanjia_90010505_22_dialog_content = "Tengo mucha sal aquí. Puedes pasarte en cualquier momento y tomar un poco.",
  str_homestory_N19chuanshanjia_90010505_23_dialog_content = "¿En serio? ¡Eso es generoso de tu parte! Du-du!",
  str_homestory_N19chuanshanjia_90010505_24_dialog_content = "También tengo muchas bebidas en otros sabores que puedes probar la próxima vez.",
  str_homestory_N19chuanshanjia_90010505_25_dialog_content = "¡Sí! ¡Sí! ¡Pero sigo pensando que esta agua salada sabe mejor!",
  str_homestory_N19chuanshanjia_90010505_26_dialog_content = "¡Si no estás bebiendo, entonces lo retiro! Du-du!",
  str_homestory_N19chuanshanjia_90010505_27_dialog_content = "¡Ten cuidado ahí fuera!",
  str_homestory_N19chuanshanjia_90010505_28_dialog_content = "Sal, eh... Suena una campana en ese proverbio de una novela.",
  str_homestory_N19chuanshanjia_90010505_29_dialog_content = "\"Amar a una persona es como salar. Ni más ni menos\".",
  str_homestory_N19chuanshanjia_90010505_30_dialog_content = "Tal vez el verdadero secreto de esta bebida es la proporción de sal y agua.",
  str_homestory_N19chuanshanjia_90010601_1_dialog_content = "<anim type=Shake><size=65>¡La muerte es vacío! ¡La muerte es la verdad!</size></anim>",
  str_homestory_N19chuanshanjia_90010601_2_dialog_content = "Este lugar es demasiado ruidoso... Vice, ¡Me voy!",
  str_homestory_N19chuanshanjia_90010601_3_dialog_content = "¿Que es eso? ¡No puedo oírte claramente! Bueno, digas lo que digas, ¡tengo que irme!",
  str_homestory_N19chuanshanjia_90010601_4_dialog_content = "Vice, ¡Espere!",
  str_homestory_N19chuanshanjia_90010601_5_dialog_content = "Ella se fue rápidamente. De cualquier manera, la música aquí es alta.",
  str_homestory_N19chuanshanjia_90010601_6_dialog_content = "Argh, pensé que sería capaz de manejar Regina's rendimiento por ahora, pero supongo que no.",
  str_homestory_N19chuanshanjia_90010601_7_dialog_content = "¿Eso cuenta como música? Son solo sonidos retumbantes aleatorios de instrumentos musicales.",
  str_homestory_N19chuanshanjia_90010601_8_dialog_content = "¡Esta música es un regalo de Dios! ¡Inexistente en todo el mundo salvaje! ¡Eep!",
  str_homestory_N19chuanshanjia_90010601_9_dialog_content = "Este tempo, melodía, arreglo y vocal. ¡No puedo permitirme perderlo! ¡Eep!",
  str_homestory_N19chuanshanjia_90010601_10_dialog_content = "... ¿En serio?",
  str_homestory_N19chuanshanjia_90010601_11_dialog_content = "Sí, el nombre de este increíble músico es Regina.",
  str_homestory_N19chuanshanjia_90010601_12_dialog_content = "¡Ay! Por supuesto.",
  str_homestory_N19chuanshanjia_90010601_13_dialog_content = "Ella debe ser muy popular.",
  str_homestory_N19chuanshanjia_90010601_14_dialog_content = "Es un poco... Um, no sé cómo decirlo.",
  str_homestory_N19chuanshanjia_90010601_15_dialog_content = "¿Qué quieres decir? No pareces disfrutar de su música.",
  str_homestory_N19chuanshanjia_90010601_16_dialog_content = "¡Así es! Za!",
  str_homestory_N19chuanshanjia_90010601_17_dialog_content = "Sahn, Jiji, solo fuimos a echar un vistazo.",
  str_homestory_N19chuanshanjia_90010601_18_dialog_content = "Regina ¡No tenía público! Du!",
  str_homestory_N19chuanshanjia_90010601_19_dialog_content = "¿Cómo puede esto...?",
  str_homestory_N19chuanshanjia_90010601_20_dialog_content = "¡Es verdad! Regina actuaba solo.",
  str_homestory_N19chuanshanjia_90010601_21_dialog_content = "Qué lástima... Está lejos, pero puedo sentir el descontento en Reginaesta cantando",
  str_homestory_N19chuanshanjia_90010601_22_dialog_content = "Du-du! ¿Deberíamos animarla?",
  str_homestory_N19chuanshanjia_90010601_23_dialog_content = "¡Buena idea! ¡Eep!",
  str_homestory_N19chuanshanjia_90010601_24_dialog_content = "Pero se ve un poco aterradora. No es una buena idea que corramos hacia allí, ¿verdad? ¡Guau!",
  str_homestory_N19chuanshanjia_90010601_25_dialog_content = "Practiquemos cómo animar a alguien.",
  str_homestory_N19chuanshanjia_90010601_26_dialog_content = "PlayerName, ¿cómo anima Aurorian a los demás?",
  str_homestory_N19chuanshanjia_90010601_27_dialog_content = "Yo... puedo preguntarle a alguien. Mientras pueda salir de aquí...",
  str_homestory_N19chuanshanjia_90010601_28_dialog_content = "Esperaremos a saber de usted.",
  str_homestory_N19chuanshanjia_90010601_29_dialog_content = "Voy a <color=#FFB400>ve a preguntar Vice</color>. Ella todavía debería estar cerca.",
  str_homestory_N19chuanshanjia_90010602_1_dialog_content = "Uf, silencio al fin.",
  str_homestory_N19chuanshanjia_90010602_2_dialog_content = "Hola, Vice! Necesito algo de ti.",
  str_homestory_N19chuanshanjia_90010602_3_dialog_content = "No me digas que todavía quieres que te escuche Regina¡Es música!",
  str_homestory_N19chuanshanjia_90010602_4_dialog_content = "N-No, tengo una pregunta para ti.",
  str_homestory_N19chuanshanjia_90010602_5_dialog_content = "Cualquier pregunta está bien mientras no sea escuchando esa música.",
  str_homestory_N19chuanshanjia_90010602_6_dialog_content = "¿Cuál es la mejor manera de animar a alguien? Preferiblemente con mucha gente.",
  str_homestory_N19chuanshanjia_90010602_7_dialog_content = "Se parece mucho a la <color=#FFB400>apoyo</color> que <color=#FFB400>Barbara</color> Previamente mencionado.",
  str_homestory_N19chuanshanjia_90010602_8_dialog_content = "Ella pasa a estar pasando el rato junto al río. ¿Quieres ir a preguntarle?",
  str_homestory_N19chuanshanjia_90010602_9_dialog_content = "¡Eso es genial!",
  str_homestory_N19chuanshanjia_90010603_1_dialog_content = "¡La pesca es tan difícil!",
  str_homestory_N19chuanshanjia_90010603_2_dialog_content = "Hola, Barbara! ¿Salir a dar un paseo?",
  str_homestory_N19chuanshanjia_90010603_3_dialog_content = "¡Estoy pescando! ¡Es una tarea bastante difícil!",
  str_homestory_N19chuanshanjia_90010603_4_dialog_content = "Me alegra que estes aqui. ¿Cuál es la mejor manera de apoyar a alguien?",
  str_homestory_N19chuanshanjia_90010603_5_dialog_content = "No sé, ¡mi barriga está vacía ahora!",
  str_homestory_N19chuanshanjia_90010603_6_dialog_content = "¿Entonces por eso estás pescando?",
  str_homestory_N19chuanshanjia_90010603_7_dialog_content = "¡Tengo muchas ganas de sashimi! ¡Pero la pesca es tan difícil!",
  str_homestory_N19chuanshanjia_90010603_8_dialog_content = "No es difícil de pescar. ¡Dejame hacerlo!",
  str_homestory_N19chuanshanjia_90010603_9_dialog_content = "<color=#FFB400>Tres peces</color> deberían ser suficientes, ¿verdad?",
  str_homestory_N19chuanshanjia_90010603_10_dialog_content = "¡Súper suficiente!",
  str_homestory_N19chuanshanjia_90010604_1_dialog_content = "¡Pescado fresco! ¡Voy a conseguir pescado fresco!",
  str_homestory_N19chuanshanjia_90010604_2_dialog_content = "Esto es suficiente, ¿verdad? ({1}/{2})",
  str_homestory_N19chuanshanjia_90010604_3_dialog_content = "¡Sí! ¡Muy fresco!",
  str_homestory_N19chuanshanjia_90010604_4_dialog_content = "Puedes comer hasta llenarte más tarde. Puedes responder mi pregunta ahora, ¿verdad?",
  str_homestory_N19chuanshanjia_90010604_5_dialog_content = "Si quiero que varias personas animen a una persona, eso es <color=#FFB400>apoyo</color>, ¿Correcto?",
  str_homestory_N19chuanshanjia_90010604_6_dialog_content = "¿Hay algún truco?",
  str_homestory_N19chuanshanjia_90010604_7_dialog_content = "Su \"<color=#FFB400>amor</color>\"!",
  str_homestory_N19chuanshanjia_90010604_8_dialog_content = "¿Amor? ¿Solo eso?",
  str_homestory_N19chuanshanjia_90010604_9_dialog_content = "¡Es extremadamente importante!",
  str_homestory_N19chuanshanjia_90010604_10_dialog_content = "Si muestras suficiente amor, la otra persona lo sentirá con seguridad.",
  str_homestory_N19chuanshanjia_90010604_11_dialog_content = "¿Eso es todo?",
  str_homestory_N19chuanshanjia_90010604_12_dialog_content = "¡La sinceridad es mejor que cualquier truco!",
  str_homestory_N19chuanshanjia_90010604_13_dialog_content = "Lo intentaré...",
  str_homestory_N19chuanshanjia_90010604_14_dialog_content = "Pescaré un poco más.",
  str_homestory_N19chuanshanjia_90010605_1_dialog_content = "Por lo que escuché, ustedes tienen que ser lo suficientemente sinceros para demostrar su amor... y eso debería ser todo.",
  str_homestory_N19chuanshanjia_90010605_2_dialog_content = "Pero, ¿cómo expresamos el amor?",
  str_homestory_N19chuanshanjia_90010605_3_dialog_content = "Según los profesionales, la otra parte definitivamente lo sentirá si realmente les gusta.",
  str_homestory_N19chuanshanjia_90010605_4_dialog_content = "Solo tendréis que expresaros plenamente.",
  str_homestory_N19chuanshanjia_90010605_5_dialog_content = "hablando del amor Regina tiene para la música, probablemente entendemos que lo mejor!",
  str_homestory_N19chuanshanjia_90010605_6_dialog_content = "¡Sí! ¡Ese es el espíritu!",
  str_homestory_N19chuanshanjia_90010605_7_dialog_content = "Iré a discutir contramedidas con ellos. ¡Ven a ver nuestro apoyo más tarde también!",
  str_homestory_N19chuanshanjia_90010605_8_dialog_content = "Tengo que volver...?",
  str_homestory_N19chuanshanjia_90010606_1_dialog_content = "Mis oídos comenzaron a sangrar tan pronto como regresé aquí.",
  str_homestory_N19chuanshanjia_90010606_2_dialog_content = "<anim type=Shake><size=65>¡Mundo injusto! ¡Corazón ardiente!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_3_dialog_content = "Pero es como dijo Sahn. Ya sea por la letra o por el ritmo, hay una sensación de resentimiento.",
  str_homestory_N19chuanshanjia_90010606_4_dialog_content = "Parece Regina tiene muchos pensamientos que quiere expresar también...",
  str_homestory_N19chuanshanjia_90010606_5_dialog_content = "Tu estas diciendo...",
  str_homestory_N19chuanshanjia_90010606_6_dialog_content = "¡Música! ¡No te detengas! ¡Eep!",
  str_homestory_N19chuanshanjia_90010606_7_dialog_content = "Za! ¡Queremos música!",
  str_homestory_N19chuanshanjia_90010606_8_dialog_content = "Regina¡Es música! ¡El más fuerte! Du!",
  str_homestory_N19chuanshanjia_90010606_9_dialog_content = "Aquí está la última canción! Para toda la nueva audiencia!",
  str_homestory_N19chuanshanjia_90010606_10_dialog_content = "<anim type=Shake><size=65>¡Como la llegada de un gran enemigo!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_11_dialog_content = "<anim type=Shake><size=65>¡Los verdaderos enemigos realmente no son Eclipsites!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_12_dialog_content = "¡Realmente no son eclipses!",
  str_homestory_N19chuanshanjia_90010606_13_dialog_content = "¡Realmente no son eclipses!",
  str_homestory_N19chuanshanjia_90010606_14_dialog_content = "<anim type=Shake><size=65>¡Es la oscuridad de los pensamientos!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_15_dialog_content = "¡Oscuridad de pensamientos!",
  str_homestory_N19chuanshanjia_90010606_16_dialog_content = "¡Oscuridad! De pensamientos!",
  str_homestory_N19chuanshanjia_90010606_17_dialog_content = "¡Oscuridad! ¡Pensamientos!",
  str_homestory_N19chuanshanjia_90010606_18_dialog_content = "No esperaba que a los Pangalos les gustara este tipo de música.",
  str_homestory_N19chuanshanjia_90010606_19_dialog_content = "Es un sabor único...",
  str_homestory_N19chuanshanjia_90010606_20_dialog_content = "¿Escuchaste ese solo en la última parte? ¡Eso fue genial!",
  str_homestory_N19chuanshanjia_90010606_21_dialog_content = "¡Estoy lleno de poder! ¡Soy invencible!",
  str_homestory_N19chuanshanjia_90010606_22_dialog_content = "¡Estoy a punto de volar!",
  str_homestory_N19chuanshanjia_90010606_23_dialog_content = "Porqué estoy llorando...?",
  str_homestory_N19chuanshanjia_90010606_24_dialog_content = "¡Ese solo se repetirá en mi cabeza durante el próximo mes!",
  str_homestory_N19chuanshanjia_90010606_25_dialog_content = "Ustedes...",
  str_homestory_N19chuanshanjia_90010606_26_dialog_content = "He realizado muchos espectáculos, pero esta es la primera vez que tengo una audiencia como ustedes.",
  str_homestory_N19chuanshanjia_90010606_27_dialog_content = "Y esa forma de animar... Siento que lo he visto en alguna parte...",
  str_homestory_N19chuanshanjia_90010606_28_dialog_content = "Ejem, eso no es importante. Lo importante es que realmente les gusten tus canciones.",
  str_homestory_N19chuanshanjia_90010606_29_dialog_content = "¡Sí! Pude sentir su sinceridad a través de sus expresiones y lenguaje corporal.",
  str_homestory_N19chuanshanjia_90010606_30_dialog_content = "¡Ah! ¡Nos están rodeando!",
  str_homestory_N19chuanshanjia_90010606_31_dialog_content = "Regina, en nombre del Pangalo Lítico, quisiera expresar mi más sincero agradecimiento.",
  str_homestory_N19chuanshanjia_90010606_32_dialog_content = "¡Autógrafo! ¡Autógrafo! ¡Eep!",
  str_homestory_N19chuanshanjia_90010606_33_dialog_content = "¿Puedo tener un autógrafo también?",
  str_homestory_N19chuanshanjia_90010606_34_dialog_content = "Za! ¡Sahn, Tubby, Vientreverde! ¡Deja de dar vueltas! ¡Ven ahora!",
  str_homestory_N19chuanshanjia_90010606_35_dialog_content = "S-si señora Regina! ¡Yo también quiero un autógrafo!",
  str_homestory_N19chuanshanjia_90010606_36_dialog_content = "¡Jaja, no soy una dama! ¡Solo soy un rockero!",
  str_homestory_N19chuanshanjia_90010606_37_dialog_content = "Pero la forma en que estaban animando antes...",
  str_homestory_N19chuanshanjia_90010606_38_dialog_content = "¿Te enseñó ese \"bollito de crema frito\"?",
  str_homestory_N19chuanshanjia_90010606_39_dialog_content = "¡Um! les enseñé...",
  str_homestory_N19chuanshanjia_90010606_40_dialog_content = "Así que el \"bocado de crema frito\" te enseñó.",
  str_homestory_N19chuanshanjia_90010606_41_dialog_content = "Err...",
  str_homestory_N19chuanshanjia_90010606_42_dialog_content = "Pero fueron muy sinceros, y me di cuenta de que era un aprecio desde el corazón.",
  str_homestory_N19chuanshanjia_90010606_43_dialog_content = "¡Vamos! ¡Los autógrafos no son un problema! ¡Una foto juntos también está bien!",
  str_homestory_N19chuanshanjia_90010606_44_dialog_content = "Yo... ¡Me voy a desmayar! ¡Tenue! ¡Eep!",
  str_homestory_N19chuanshanjia_90010606_45_dialog_content = "¡Jiji!",
  str_homestory_N19chuanshanjia_90010606_46_dialog_content = "Vientreverde! ¡Ayúdame a levantar a Jiji!",
  str_homestory_N19chuanshanjia_90010606_47_dialog_content = "¡Una foto del grupo g!",
  str_homestory_N19chuanshanjia_90010606_48_dialog_content = "Jajajaja... Es tan satisfactorio...",
  str_homestory_N19chuanshanjia_90010606_49_dialog_content = "(Me pregunto si debería recordarles que no hay cámaras en los Jardines de las Nubes...)",
  str_homestory_N19chuanshanjia_90010611_1_dialog_content = "Ella está junto al río.",
  str_homestory_N19chuanshanjia_90010612_1_dialog_content = "3 peces... eso es suficiente para mantenerme alimentado por un tiempo!",
  str_homestory_N19chuanshanjia_90010613_1_dialog_content = "¡Recuerda! ¡La sinceridad es la clave!",
  str_homestory_N19chuanshanjia_90010614_1_dialog_content = "Vaya, no pueden esperar más.",
  str_homestory_N19chuanshanjia_90010113_1_dialog_content = "¿Hay otros animales que hablan?",
  str_homestory_N19chuanshanjia_90010114_1_dialog_content = "Has encontrado Korgon?",
  str_homestory_N19chuanshanjia_90010115_1_dialog_content = "Ha pasado mucho tiempo... ¿Existen realmente otros animales parlantes?",
  str_homestory_N19chuanshanjia_90010116_1_dialog_content = "¡Rápidamente! Sahn se irá si eres demasiado lento."
}
return config
